class MethodBoundaryChecks {
    public static void main(String[] args) {
        if (MethodDemo.addition(3, -3) != 0) throw new AssertionError("addition");
        if (MinimumDemo.min(9, 7, 2) != 2) throw new AssertionError("second comparison");
        if (MinimumDemo.min(4, 4, 4) != 4) throw new AssertionError("equal minimum");
        if (VarargsSumDemo.sum() != 0) throw new AssertionError("empty");
        if (VarargsSumDemo.sum(-5, 2) != -3) throw new AssertionError("signed");
        if (VarargsSumDemo.sum(2147483647, 0) != 2147483647) throw new AssertionError("int boundary");
        if (VarargsSumDemo.sum(new int[] {4, 5}) != 9) throw new AssertionError("array representation");
        if (VarargsSumDemo.sum(4, 6, 1) != 11) throw new AssertionError("review answer");
        if (AverageDemo.average(1, 2, 2) != 5.0 / 3.0) throw new AssertionError("fraction");
        if (AverageDemo.average(-3, 0, 3) != 0.0) throw new AssertionError("signed average");
        System.out.println("10 method boundary checks passed");
    }
}
